<script setup>const {data:me}=await useFetch('/api/me');if(me.value?.role==='USER')await navigateTo('/');const {data:apps,refresh}=await useFetch('/api/admin/apps');const form=reactive({name:'',url:'',description:'',icon:'◫'}),error=ref('');async function add(){try{await $fetch('/api/admin/apps',{method:'POST',body:form});Object.assign(form,{name:'',url:'',description:'',icon:'◫'});error.value='';refresh()}catch(e){error.value=e.data?.statusMessage||'Gagal'}}async function del(id){await $fetch(`/api/admin/apps/${id}`,{method:'DELETE'});refresh()}</script><template><header class="top"><div class="brand">AppDesk Admin</div><nav class="nav"><NuxtLink to="/">Dashboard</NuxtLink></nav></header><main class="wrap"><h1>Kelola Aplikasi</h1><section class="card"><h2>Tambah aplikasi</h2><div class="grid"><input v-model="form.name" class="field" placeholder="Nama"><input v-model="form.url" class="field" placeholder="https://..."><input v-model="form.description" class="field" placeholder="Deskripsi"><input v-model="form.icon" class="field" placeholder="Ikon"></div><p v-if="error" class="error">{{error}}</p><button class="btn" @click="add">Simpan</button></section><section class="section"><table class="table"><thead><tr><th>Aplikasi</th><th>URL</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="a in apps" :key="a.id"><td>{{a.icon}} {{a.name}}</td><td>{{a.url}}</td><td><span class="pill">Aktif</span></td><td><button class="btn danger" @click="del(a.id)">Hapus</button></td></tr></tbody></table></section></main></template>